'use strict';

/**
* Compute a norm of a double-precision triangular or trapezoidal matrix.
*
* @module @stdlib/lapack/base/dlantr
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlantr = require( '@stdlib/lapack/base/dlantr' );
*
* var A = new Float64Array( [ 2.0, -3.0, 4.0, NaN, 5.0, -6.0 ] );
* var work = new Float64Array( 2 );
*
* var v = dlantr( 'row-major', 'infinity', 'upper', 'non-unit', 2, 3, A, 3, work );
* // returns 11.0
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlantr;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlantr = main;
} else {
	dlantr = tmp;
}


// EXPORTS //

module.exports = dlantr;

// exports: { "ndarray": "dlantr.ndarray" }
